import django.db.models.deletion
from django.db import migrations, models


def link_old_packages(apps, schema_editor):
    """Packages made before jobs existed were named after the manifest. Link
    each one to its job when the manifest has exactly one job report."""
    SQBPackage = apps.get_model("sqb", "SQBPackage")
    JobReport = apps.get_model("job_reports", "JobReport")
    for package in SQBPackage.objects.filter(job_report__isnull=True):
        matches = list(JobReport.objects.filter(manifest__job_name=package.job_name)[:2])
        if len(matches) == 1:
            package.job_report = matches[0]
            package.save(update_fields=["job_report"])


